INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('INTE.G8.FORCE_.PRESSURE.a', 'INTE.G8.FORCE_.PRESSURE', 'a', 'demonstrate pressure in solids and liquids', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('INTE.G8.FORCE_.PRESSURE.b', 'INTE.G8.FORCE_.PRESSURE', 'b', 'identify applications of pressure in solids and liquids', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
