INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ATOM_ELEMENT', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS', 'integrated_science', 8, 'Tell an atom, an element, a molecule and a compound apart', ARRAY['INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.a']::text[], 'The child says an atom is the smallest particle of an element, an element is made of one kind of atom (oxygen, iron), a molecule is two or more atoms joined (water, oxygen gas) and a compound is made of different elements joined chemically (water, salt). The child does not say a compound is a mixture or an atom is a molecule. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the word from its description","say what a compound is made of","sort substances into elements and compounds","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.SYMBOLS', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS', 'integrated_science', 8, 'Give the symbols of common elements', ARRAY['INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.b']::text[], 'The child gives the symbols H (hydrogen), O (oxygen), C (carbon), N (nitrogen), S (sulphur), Na (sodium), K (potassium), Ca (calcium), Mg (magnesium), Fe (iron), Cu (copper), Zn (zinc), Al (aluminium), Cl (chlorine), Ag (silver) and Au (gold), writes a capital first letter and a small second letter, and does not give the first letter of the name for iron, sodium or potassium. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the symbol of an element","pick the element of a symbol","say how a symbol is written","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.WORD_EQUATIONS', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS', 'integrated_science', 8, 'Write word equations for reactions of elements', ARRAY['INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.c']::text[], 'The child writes a word equation with the reactants first, an arrow and the product (magnesium + oxygen gives magnesium oxide; iron + sulphur gives iron sulphide; hydrogen + oxygen gives water; carbon + oxygen gives carbon dioxide; sodium + chlorine gives sodium chloride), names the compound from the elements (an oxide from oxygen, a sulphide from sulphur, a chloride from chlorine), and does not put the product first. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the word equation","name the product","put the reactants and product in order","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ELEMENT_USES', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS', 'integrated_science', 8, 'Say what common elements are used for', ARRAY['INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.d', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.e']::text[], 'The child says copper is used for electric wires, iron for tools and nails, aluminium for cooking pots and foil, carbon for charcoal and pencils, nitrogen in fertilisers, chlorine to make water safe and oxygen for breathing, and that a packaging label tells the contents, the amounts and the dates to use it by. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the use of an element","pick the element for a use","say what a label tells","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.STATES_PARTICLES', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH', 'integrated_science', 8, 'Describe the particles in solids, liquids and gases', ARRAY['INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.a']::text[], 'The child says the particles of a solid are close together in fixed places and only vibrate, the particles of a liquid are close but slide past each other, and the particles of a gas are far apart and move freely in all directions, and does not say solid particles do not move. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the particle picture of a state","say how close the particles are","say how the particles move","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.IMPURITIES', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH', 'integrated_science', 8, 'Say how impurities change melting and boiling points', ARRAY['INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.b']::text[], 'The child says a pure substance melts and boils at fixed temperatures (pure water melts at 0 degrees Celsius and boils at 100), that impurities raise the boiling point and lower the melting point (salty water boils above 100 degrees and freezes below 0), and does not say impurities lower the boiling point. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what pure water does","say what salt does to the boiling point","say what an impurity does to the melting point","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.CHANGES', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH', 'integrated_science', 8, 'Tell a physical change from a chemical change', ARRAY['INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.c', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.d']::text[], 'The child says a physical change makes no new substance and can usually be reversed (melting ice, dissolving sugar, boiling water), a chemical change makes a new substance and is usually not reversible (burning wood, rusting iron, cooking an egg, milk going sour), and does not call burning physical or melting chemical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["sort a change","say what a new substance shows","pick a use of a change of state","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_TRIANGLE', 'INTE.G8.MIXTUR.CLASSES_OF_FIRE', 'integrated_science', 8, 'Say what a fire needs and how taking one away puts it out', ARRAY['INTE.G8.MIXTUR.CLASSES_OF_FIRE.a', 'INTE.G8.MIXTUR.CLASSES_OF_FIRE.b']::text[], 'The child says a fire needs heat, fuel and oxygen, that taking away any one puts the fire out (cooling with water removes heat, a blanket removes oxygen, clearing dry grass removes fuel), names natural causes (lightning, volcanic eruptions, dry grass lit by the hot sun) and does not say fire needs only heat and fuel. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the parts of the fire triangle","say which part to remove","pick a cause of fire in nature","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_CLASSES', 'INTE.G8.MIXTUR.CLASSES_OF_FIRE', 'integrated_science', 8, 'Choose the right way to put out different classes of fire', ARRAY['INTE.G8.MIXTUR.CLASSES_OF_FIRE.c']::text[], 'The child says water suits a fire of wood, paper or cloth, that an oil or petrol fire is smothered with sand, a blanket or foam and never put out with water, that an electrical fire needs the power switched off and a dry powder or carbon dioxide extinguisher and never water, and that the first step is to raise the alarm and keep safe. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick what puts out a wood fire","pick what to use on an oil fire","say what to do about an electrical fire","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.LIVING.THE_CELL.CELL_PARTS', 'INTE.G8.LIVING.THE_CELL', 'integrated_science', 8, 'Name the parts of plant and animal cells and what each does', ARRAY['INTE.G8.LIVING.THE_CELL.a', 'INTE.G8.LIVING.THE_CELL.b', 'INTE.G8.LIVING.THE_CELL.c']::text[], 'The child says both cells have a cell membrane (controls what enters and leaves), cytoplasm (where reactions happen) and a nucleus (controls the cell), and that plant cells also have a cell wall (supports the cell), chloroplasts (make food with light) and a large vacuole (stores sap), and does not give an animal cell a cell wall or a chloroplast. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the part from its job","pick the part only plant cells have","compare plant and animal cells","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.LIVING.THE_CELL.MAGNIFICATION', 'INTE.G8.LIVING.THE_CELL', 'integrated_science', 8, 'Work out the magnification of a light microscope', ARRAY['INTE.G8.LIVING.THE_CELL.d']::text[], 'The child multiplies the magnification of the eyepiece and the objective lens (10 times 40 gives 400 times), says each lens magnifies and the total is the product, and does not add the two numbers or use only the objective. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["calculate the total magnification","say what the eyepiece and objective do","pick the units","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS', 'INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN', 'integrated_science', 8, 'Say what diffusion and osmosis are and why living things need them', ARRAY['INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.a', 'INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.c']::text[], 'The child says diffusion is the spreading of particles from where there are many to where there are few until they are even, osmosis is the movement of water through a thin membrane from a weak solution to a stronger one, gives examples (the smell of cooking, the uptake of water by root hairs, oxygen entering blood), and says neither needs energy from the cell. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the process from a description","say which way particles move","say what diffusion or osmosis does in a living thing","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS_DEMO', 'INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN', 'integrated_science', 8, 'Predict and explain the results of simple diffusion and osmosis demonstrations', ARRAY['INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.b']::text[], 'Given a set-up (a drop of dye or potassium permanganate in still water, raw potato strips in salty and in plain water, a raisin or a dry bean soaked in water, a smell spreading through a room), the child predicts the result (the colour spreads until even; strips in salty water go soft and shorter, in plain water firm and longer; the raisin swells) and explains it by particles spreading from many to few or water moving through a membrane from a weak to a strong solution. The child does not say the salt moves into the potato in osmosis. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["predict what a demonstration will show","explain a result in terms of particles or water moving","pick the fair way to set up the demonstration","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE', 'integrated_science', 8, 'Outline the menstrual cycle and how to manage its challenges', ARRAY['INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.a']::text[], 'The child says the cycle is about 28 days, the bleeding (menstruation) lasts about three to seven days, an egg is released about the middle of the cycle (ovulation), the cycle is normal and not an illness, and picks healthy ways to cope (clean pads or cloths changed often, bathing, rest, warm drinks, talking to a trusted adult and seeing a health worker for severe pain). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say how long the cycle is","say when an egg is released","pick a healthy way to manage cramps or bleeding","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL_MANAGE', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE', 'integrated_science', 8, 'Choose the parts of a plan that manage the challenges of the menstrual cycle', ARRAY['INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.b']::text[], 'For a named challenge (cramps, heavy bleeding, missing school, no pads, feeling moody, teasing), the child picks a healthy step (a clean pad or cloth changed every four to six hours, bathing daily, a warm drink and rest, a trusted adult or the school nurse, a spare pad in the bag, a health worker for severe pain or very heavy bleeding) and keeps going to school. The child does not say the cycle should be kept secret from every adult or treated with any medicine without advice. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the healthy way to manage a named challenge","say what is missing from a learner''s plan","decide when to see a health worker","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.FERTILISATION', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE', 'integrated_science', 8, 'Describe fertilisation and implantation in order', ARRAY['INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.c']::text[], 'The child says fertilisation is a sperm joining an egg in the oviduct to make a zygote, the zygote divides as it travels to the uterus, and implantation is the embryo attaching to the wall of the uterus, and puts the events in that order. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["put the events in order","say where fertilisation happens","say what the zygote is","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.STIS', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE', 'integrated_science', 8, 'Name the symptoms of common STIs and how to prevent them', ARRAY['INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.d', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.e']::text[], 'The child names STIs (HIV, syphilis, gonorrhoea, chlamydia), symptoms (unusual discharge, pain when passing urine, sores, itching), knows they are not spread by hugging, shaking hands or toilet seats, and picks prevention (abstinence, faithfulness to one uninfected partner, not sharing needles or razors, testing and treatment, going to a health worker). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a symptom of an STI","pick a way an STI is NOT spread","pick a prevention measure","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_FORMS_SOURCES', 'INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY', 'integrated_science', 8, 'Name forms of energy and sort sources into renewable and non-renewable', ARRAY['INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.a', 'INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.b']::text[], 'The child names forms (kinetic, potential, heat, light, sound, electrical, chemical), sorts renewable sources (the sun, wind, flowing water, geothermal, biogas) from non-renewable ones (coal, petroleum, natural gas), and knows Kenya uses geothermal (Olkaria), hydro and wind (Lake Turkana) power. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the form of energy","sort a source","pick a Kenyan source","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_TRANSFORM', 'INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY', 'integrated_science', 8, 'Say how energy changes from one form to another and how to stay safe', ARRAY['INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.c', 'INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.d']::text[], 'The child says energy changes form and is never created or used up (an electric kettle changes electrical energy to heat, a solar panel light to electrical, a lamp electrical to light, falling water potential to kinetic to electrical, a burning match chemical to heat and light) and picks safety measures (do not touch bare wires, keep flammable things away from heat, ask an adult). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the transformation","pick what a device changes energy into","pick the safety measure","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G8.FORCE_.PRESSURE.PRESSURE', 'INTE.G8.FORCE_.PRESSURE', 'integrated_science', 8, 'Say how force, area and depth change pressure', ARRAY['INTE.G8.FORCE_.PRESSURE.a', 'INTE.G8.FORCE_.PRESSURE.b']::text[], 'The child says pressure is the force on each unit of area, so the same force on a smaller area makes a bigger pressure (a sharp knife, a nail) and on a larger area a smaller pressure (wide tyres, snow shoes), calculates pressure as force divided by area, and says liquid pressure grows with depth (a dam wall is thicker at the bottom). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the way to increase pressure","calculate the pressure from the force and the area","say how liquid pressure changes with depth","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ATOM_ELEMENT', 'INTE.G7.MIXTUR.MIXTURES.HOMOGENEOUS_SOLUTION', 'skill', 'essential', 'Grade 7 Integrated Science taught it first. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ATOM_ELEMENT', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_COMPONENTS', 'skill', 'essential', 'Air as a mixture of gases (Grade 6) gives the first elements (nitrogen, oxygen) and a compound (carbon dioxide) by name. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.SYMBOLS', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ATOM_ELEMENT', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.SYMBOLS', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_BASE', 'skill', 'essential', 'Writing unit symbols with the right capital and small letters (m, kg, A) is the same habit used for element symbols. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.WORD_EQUATIONS', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.SYMBOLS', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.WORD_EQUATIONS', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ATOM_ELEMENT', 'skill', 'essential', 'Naming the product needs the difference between an element and a compound. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ELEMENT_USES', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.SYMBOLS', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ELEMENT_USES', 'INTE.G7.FORCE_.ELECTRICAL_ENERGY.CIRCUIT_BASICS', 'skill', 'essential', 'Copper wires in circuits (Grade 7) are the first use of an element the child has handled. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.STATES_PARTICLES', 'SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_NAMES', 'skill', 'essential', 'Grade 6 Science and Technology taught it first. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
