INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ATOM_ELEMENT.M_G8_AE_ATOM_MOLECULE', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ATOM_ELEMENT', 'Says an atom and a molecule are the same.', '{"question":"What is a molecule?","wrong_answer":"The smallest particle of an element","correct_answer":"Two or more atoms joined together"}'::jsonb, 'Hears both words used for "a tiny particle" and has never seen atoms joined into a molecule.', 'Offer "The smallest particle of an element" next to the right answer in a new question and ask the child to choose.', 'Build an oxygen molecule from two balls.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ATOM_ELEMENT.M_G8_AE_ELEMENT_COMPOUND', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ATOM_ELEMENT', 'Says a compound is made of one kind of atom.', '{"question":"What is a compound?","wrong_answer":"A substance made of one kind of atom","correct_answer":"A substance made of different elements joined chemically"}'::jsonb, 'Remembers "one kind" from the definition of an element and attaches it to the wrong word.', 'Offer "A substance made of one kind of atom" next to the right answer in a new question and ask the child to choose.', 'Compare iron (one kind) and water (hydrogen and oxygen).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ATOM_ELEMENT.M_G8_AE_MIXTURE', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ATOM_ELEMENT', 'Says a compound is the same as a mixture.', '{"question":"How is a compound different from a mixture?","wrong_answer":"It is not different","correct_answer":"Its elements are joined chemically and cannot be separated easily"}'::jsonb, 'Both a mixture and a compound have more than one substance in them, so the child sees no difference.', 'Offer "It is not different" next to the right answer in a new question and ask the child to choose.', 'Try to separate iron filings from sand and then iron from iron sulphide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.SYMBOLS.M_G8_SY_FIRST_LETTER', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.SYMBOLS', 'Gives the first letter of the name for every element (I for iron, S for sodium).', '{"question":"What is the symbol for iron?","wrong_answer":"I","correct_answer":"Fe"}'::jsonb, 'Most symbols the child meets first (H, O, C, N) are the first letter, so the child makes it a rule.', 'Offer "I" next to the right answer in a new question and ask the child to choose.', 'Some symbols come from old Latin names: ferrum for iron, natrium for sodium.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.SYMBOLS.M_G8_SY_NAME', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.SYMBOLS', 'Reads K as calcium (or Ca as potassium), matching the symbol to an element whose name starts with the same sound.', '{"question":"Which element has the symbol K?","wrong_answer":"Calcium","correct_answer":"Potassium"}'::jsonb, 'K sounds like the start of "calcium"; the Latin name kalium is not known.', 'Offer "Calcium" next to the right answer in a new question and ask the child to choose.', 'Make a card for each symbol and its name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.WORD_EQUATIONS.M_G8_WE_ORDER', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.WORD_EQUATIONS', 'Puts the product first.', '{"question":"Which word equation is correct?","wrong_answer":"magnesium oxide gives magnesium + oxygen","correct_answer":"magnesium + oxygen gives magnesium oxide"}'::jsonb, 'Reads an equation like a sum written backwards, with the answer first.', 'Offer "magnesium oxide gives magnesium + oxygen" next to the right answer in a new question and ask the child to choose.', 'Read the equation from the left: what we start with.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.WORD_EQUATIONS.M_G8_WE_NAME', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.WORD_EQUATIONS', 'Gives the wrong name to the compound (iron sulphate for iron sulphide).', '{"question":"What is made when iron reacts with sulphur?","wrong_answer":"Iron sulphate","correct_answer":"Iron sulphide"}'::jsonb, 'Has heard "sulphate" more often (on fertiliser bags) than "sulphide".', 'Offer "Iron sulphate" next to the right answer in a new question and ask the child to choose.', 'A compound of two elements ends in -ide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.WORD_EQUATIONS.M_G8_WE_LOST', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.WORD_EQUATIONS', 'Says the mass or the elements disappear in a reaction.', '{"question":"What happens to the atoms in a reaction?","wrong_answer":"They disappear","correct_answer":"They rearrange to make new substances"}'::jsonb, 'Sees a solid burn away or a gas leave and thinks the matter has gone.', 'Offer "They disappear" next to the right answer in a new question and ask the child to choose.', 'Weigh steel wool before and after it rusts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ELEMENT_USES.M_G8_EU_WRONG_USE', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ELEMENT_USES', 'Picks aluminium foil, not copper, as the element used for electric wires, because foil is a shiny metal at home.', '{"question":"Which element is used for electric wires?","wrong_answer":"Aluminium foil","correct_answer":"Copper"}'::jsonb, 'Knows wires are metal and picks the metal seen most often in the kitchen.', 'Offer "Aluminium foil" next to the right answer in a new question and ask the child to choose.', 'Match each element to an object at home.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ELEMENT_USES.M_G8_EU_LABEL', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ELEMENT_USES', 'Says packaging labels are only for decoration.', '{"question":"What does a packaging label tell you?","wrong_answer":"Nothing useful","correct_answer":"The contents, amounts and the date to use it by"}'::jsonb, 'Has only looked at the picture and brand name on a packet.', 'Offer "Nothing useful" next to the right answer in a new question and ask the child to choose.', 'Read a label together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ELEMENT_USES.M_G8_EU_COMPOUND_ELEMENT', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ELEMENT_USES', 'Calls a compound such as water or salt an element.', '{"question":"Which of these is an element?","wrong_answer":"Water","correct_answer":"Oxygen"}'::jsonb, 'Water and salt are everyday "pure" things, so the child takes them to be single elements.', 'Offer "Water" next to the right answer in a new question and ask the child to choose.', 'Ask what water is made of.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ATOM_ELEMENT.M_G8_AE_GAS_NOT_ELEMENT', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ATOM_ELEMENT', 'Thinks a gas such as oxygen or nitrogen cannot be an element, because elements are solids like iron.', '{"question":"Is oxygen an element?","wrong_answer":"No, elements are solids such as iron and copper","correct_answer":"Yes: oxygen is made of one kind of atom"}'::jsonb, 'Has met elements as metals first.', 'Offer "No, elements are solids such as iron and copper" next to the right answer and ask the question again in a new context.', 'Sort a list (iron, oxygen, copper, nitrogen, water) by "one kind of atom or more".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.SYMBOLS.M_G8_SY_CAPITALS', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.SYMBOLS', 'Writes both letters of a symbol as capitals (CU, NA) or the first as a small letter (fe).', '{"question":"How is the symbol for copper written?","wrong_answer":"CU","correct_answer":"Cu"}'::jsonb, 'Has not noticed that the second letter is small.', 'Offer "CU" next to the right answer and ask the question again in a new context.', 'Show that CO is carbon monoxide (two elements) but Co is cobalt (one).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.SYMBOLS.M_G8_SY_SILVER_GOLD', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.SYMBOLS', 'Swaps the symbols for silver (Ag) and gold (Au).', '{"question":"What is the symbol for gold?","wrong_answer":"Ag","correct_answer":"Au"}'::jsonb, 'Both come from Latin names the child does not know and both start with A.', 'Offer "Ag" next to the right answer and ask the question again in a new context.', 'Link them: Au is from aurum, gold; Ag is from argentum, silver.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.WORD_EQUATIONS.M_G8_WE_PLUS_PRODUCT', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.WORD_EQUATIONS', 'Writes the product as the two element names joined with "and" (magnesium and oxygen) instead of the new compound.', '{"question":"Magnesium burns in oxygen. What is the product?","wrong_answer":"Magnesium and oxygen","correct_answer":"Magnesium oxide"}'::jsonb, 'Thinks the reactants are still there side by side after the reaction.', 'Offer "Magnesium and oxygen" next to the right answer and ask the question again in a new context.', 'Show burnt magnesium: a white powder, not the shiny metal and a gas.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ELEMENT_USES.M_G8_EU_CHLORINE_FOOD', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ELEMENT_USES', 'Thinks chlorine is a food element because it is in table salt, so the gas is safe to breathe.', '{"question":"Chlorine is used to treat water. Is chlorine gas safe to breathe?","wrong_answer":"Yes, it is in salt we eat","correct_answer":"No: chlorine gas is toxic; in salt it is joined with sodium as a compound"}'::jsonb, 'Does not see that a compound has different properties from its elements.', 'Offer "Yes, it is in salt we eat" next to the right answer and ask the question again in a new context.', 'Compare the hazard label on a chlorine product with a salt packet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.STATES_PARTICLES.M_G8_ST_SOLID_STILL', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.STATES_PARTICLES', 'Says the particles of a solid do not move at all.', '{"question":"How do the particles of a solid move?","wrong_answer":"They do not move at all","correct_answer":"They vibrate in fixed places"}'::jsonb, 'A solid looks still, so the child thinks its particles are still.', 'Offer "They do not move at all" next to the right answer in a new question and ask the child to choose.', 'Think of people standing in a queue who shake in place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.STATES_PARTICLES.M_G8_ST_GAS_CLOSE', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.STATES_PARTICLES', 'Says the particles of a gas are close together.', '{"question":"How far apart are the particles of a gas?","wrong_answer":"Close together","correct_answer":"Far apart"}'::jsonb, 'Pictures a gas as a thick cloud, like smoke, rather than as empty space.', 'Offer "Close together" next to the right answer in a new question and ask the child to choose.', 'Think of why a gas can be squeezed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.STATES_PARTICLES.M_G8_ST_LIQUID_FIXED', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.STATES_PARTICLES', 'Says the particles of a liquid are fixed in place.', '{"question":"How do the particles of a liquid move?","wrong_answer":"They stay in fixed places","correct_answer":"They slide past one another"}'::jsonb, 'Water in a glass looks still, and the child applies the solid picture to it.', 'Offer "They stay in fixed places" next to the right answer in a new question and ask the child to choose.', 'Think of why a liquid takes the shape of its container.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.IMPURITIES.M_G8_IM_LOWER_BOIL', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.IMPURITIES', 'Says impurities lower the boiling point.', '{"question":"What does salt do to the boiling point of water?","wrong_answer":"It lowers it","correct_answer":"It raises it"}'::jsonb, 'Has heard that salt makes water cook food faster and takes that to mean it boils sooner.', 'Offer "It lowers it" next to the right answer in a new question and ask the child to choose.', 'Boil pure water and salty water and compare the temperature.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.IMPURITIES.M_G8_IM_RAISE_MELT', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.IMPURITIES', 'Says impurities raise the melting point.', '{"question":"What does an impurity do to the melting point of ice?","wrong_answer":"It raises it","correct_answer":"It lowers it"}'::jsonb, 'Gives impurities the same effect on melting as on boiling.', 'Offer "It raises it" next to the right answer in a new question and ask the child to choose.', 'Salt on icy roads helps ice to melt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.IMPURITIES.M_G8_IM_NO_EFFECT', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.IMPURITIES', 'Says impurities have no effect.', '{"question":"Does salt change how water boils?","wrong_answer":"No effect at all","correct_answer":"Yes, it boils at a higher temperature"}'::jsonb, 'A pinch of salt seems too small to change anything.', 'Offer "No effect at all" next to the right answer in a new question and ask the child to choose.', 'Measure the temperatures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.CHANGES.M_G8_CH_MELT_CHEMICAL', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.CHANGES', 'Calls melting a chemical change.', '{"question":"Is melting ice a physical or chemical change?","wrong_answer":"Chemical","correct_answer":"Physical"}'::jsonb, 'Melting looks like a big change, so the child calls it chemical.', 'Offer "Chemical" next to the right answer in a new question and ask the child to choose.', 'Ask whether a new substance is made.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.CHANGES.M_G8_CH_BURN_PHYSICAL', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.CHANGES', 'Calls burning a physical change.', '{"question":"Is burning wood a physical or chemical change?","wrong_answer":"Physical","correct_answer":"Chemical"}'::jsonb, 'Sees burning as only a change of state (wood "melts" into smoke).', 'Offer "Physical" next to the right answer in a new question and ask the child to choose.', 'Ask whether the ash can turn back into wood.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.CHANGES.M_G8_CH_NEW', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.CHANGES', 'Says a physical change makes a new substance.', '{"question":"What does a chemical change make?","wrong_answer":"No new substance","correct_answer":"A new substance"}'::jsonb, 'Mixes up the two definitions taught side by side.', 'Offer "No new substance" next to the right answer in a new question and ask the child to choose.', 'Compare dissolving sugar and burning sugar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.STATES_PARTICLES.M_G8_ST_PARTICLES_EXPAND', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.STATES_PARTICLES', 'Thinks the particles themselves get bigger when a substance is heated and expands.', '{"question":"A metal rod gets longer when heated. What happens to its particles?","wrong_answer":"Each particle gets bigger","correct_answer":"The particles move more and take up more space; they do not get bigger"}'::jsonb, 'Sees the whole thing grow and gives the particles the same property.', 'Offer "Each particle gets bigger" next to the right answer and ask the question again in a new context.', 'Act it out: learners shake harder and need more room, but stay the same size.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.IMPURITIES.M_G8_IM_PURITY_BY_LOOK', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.IMPURITIES', 'Thinks a clear liquid must be pure, so its boiling point cannot show an impurity.', '{"question":"Two clear liquids boil at 100 degrees and 103 degrees. Which is pure water?","wrong_answer":"Either, they both look clear","correct_answer":"The one that boils at 100 degrees"}'::jsonb, 'Judges purity by how it looks.', 'Offer "Either, they both look clear" next to the right answer and ask the question again in a new context.', 'Boil tap water and clear salty water side by side with a thermometer (teacher).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.CHANGES.M_G8_CH_DISSOLVE_CHEMICAL', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.CHANGES', 'Calls dissolving sugar in water a chemical change because the sugar seems to disappear.', '{"question":"Is dissolving sugar in tea a physical or a chemical change?","wrong_answer":"Chemical, the sugar is gone","correct_answer":"Physical: the sugar can be got back by evaporating the water"}'::jsonb, 'Thinks "it vanished" means a new substance.', 'Offer "Chemical, the sugar is gone" next to the right answer and ask the question again in a new context.', 'Evaporate sugar water on a saucer: sugar is left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_TRIANGLE.M_G8_FT_TWO_PARTS', 'INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_TRIANGLE', 'Says a fire needs only heat and fuel.', '{"question":"What three things does a fire need?","wrong_answer":"Heat and fuel only","correct_answer":"Heat, fuel and oxygen"}'::jsonb, 'Oxygen cannot be seen, so the child leaves it out of the list.', 'Offer "Heat and fuel only" next to the right answer in a new question and ask the child to choose.', 'Cover a burning candle with a jar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_TRIANGLE.M_G8_FT_WATER_ALL', 'INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_TRIANGLE', 'Says water puts out every fire.', '{"question":"Which fire is NOT put out with water?","wrong_answer":"A wood fire","correct_answer":"An oil fire"}'::jsonb, 'Has only seen wood fires put out with water.', 'Offer "A wood fire" next to the right answer in a new question and ask the child to choose.', 'Ask why oil floats and spreads on water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_TRIANGLE.M_G8_FT_CAUSE', 'INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_TRIANGLE', 'Gives a lit match (a human cause) when asked for a natural cause of fire, leaving out lightning and the sun on dry grass.', '{"question":"Which is a natural cause of fire?","wrong_answer":"A lit match","correct_answer":"Lightning"}'::jsonb, 'Thinks of the way fires are usually lit at home, not of causes in nature.', 'Offer "A lit match" next to the right answer in a new question and ask the child to choose.', 'List natural and human causes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_CLASSES.M_G8_FC_WATER_OIL', 'INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_CLASSES', 'Uses water on an oil fire.', '{"question":"What should you use on a cooking oil fire?","wrong_answer":"Water","correct_answer":"A damp cloth or a lid to cut off the air"}'::jsonb, 'Uses water on every fire because that is what is at hand.', 'Offer "Water" next to the right answer in a new question and ask the child to choose.', 'Ask what water does to hot oil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_CLASSES.M_G8_FC_WATER_ELEC', 'INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_CLASSES', 'Uses water on an electrical fire.', '{"question":"What should you do first in an electrical fire?","wrong_answer":"Pour water on it","correct_answer":"Switch off the power"}'::jsonb, 'Does not link water with conducting electricity.', 'Offer "Pour water on it" next to the right answer in a new question and ask the child to choose.', 'Ask why water and electricity are dangerous together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_CLASSES.M_G8_FC_ALARM', 'INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_CLASSES', 'Tries to fight a large fire alone.', '{"question":"A fire is spreading fast. What should a child do?","wrong_answer":"Fight it alone with water","correct_answer":"Raise the alarm and get out safely"}'::jsonb, 'Wants to help and does not know how fast a fire spreads.', 'Offer "Fight it alone with water" next to the right answer in a new question and ask the child to choose.', 'Practise the fire drill.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_TRIANGLE.M_G8_FT_FAN_PUTS_OUT', 'INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_TRIANGLE', 'Thinks fanning or blowing on a fire always puts it out.', '{"question":"Why does fanning a charcoal jiko make it burn brighter?","wrong_answer":"It does not; fanning puts fires out","correct_answer":"Fanning brings more oxygen to the fire"}'::jsonb, 'Has blown out a match and generalises.', 'Offer "It does not; fanning puts fires out" next to the right answer and ask the question again in a new context.', 'Fan a jiko (adult) and watch the charcoal glow brighter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_CLASSES.M_G8_FC_ONE_EXTINGUISHER', 'INTE.G8.MIXTUR.CLASSES_OF_FIRE.FIRE_CLASSES', 'Thinks any fire extinguisher can be used on any fire.', '{"question":"Can a water extinguisher be used on a fire in a petrol tank?","wrong_answer":"Yes, any extinguisher works","correct_answer":"No: petrol fires need foam, powder or carbon dioxide; water spreads them"}'::jsonb, 'Has not seen the labels on extinguishers.', 'Offer "Yes, any extinguisher works" next to the right answer and ask the question again in a new context.', 'Read the class labels on the school extinguisher.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.THE_CELL.CELL_PARTS.M_G8_CP_WALL_ANIMAL', 'INTE.G8.LIVING.THE_CELL.CELL_PARTS', 'Gives an animal cell a cell wall.', '{"question":"Which cell has a cell wall?","wrong_answer":"An animal cell","correct_answer":"A plant cell"}'::jsonb, 'Draws every cell as a box with a thick outline, as in plant pictures.', 'Offer "An animal cell" next to the right answer in a new question and ask the child to choose.', 'Look at pictures of both cells.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.THE_CELL.CELL_PARTS.M_G8_CP_NUCLEUS', 'INTE.G8.LIVING.THE_CELL.CELL_PARTS', 'Says the nucleus makes food.', '{"question":"What does the nucleus do?","wrong_answer":"Makes food","correct_answer":"Controls the cell"}'::jsonb, 'Knows the nucleus is the most important part and gives it the most important job it can think of, food.', 'Offer "Makes food" next to the right answer in a new question and ask the child to choose.', 'Link the nucleus with the control centre.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.THE_CELL.CELL_PARTS.M_G8_CP_CHLORO', 'INTE.G8.LIVING.THE_CELL.CELL_PARTS', 'Puts chloroplasts in animal cells.', '{"question":"Which cell has chloroplasts?","wrong_answer":"An animal cell","correct_answer":"A plant leaf cell"}'::jsonb, 'Learns the parts as one list without sorting by plant and animal.', 'Offer "An animal cell" next to the right answer in a new question and ask the child to choose.', 'Ask which living things make their own food.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.THE_CELL.CELL_PARTS.M_G8_CP_MEMBRANE', 'INTE.G8.LIVING.THE_CELL.CELL_PARTS', 'Says the cell membrane only gives the cell its shape.', '{"question":"What does the cell membrane do?","wrong_answer":"Gives the cell its shape only","correct_answer":"Controls what enters and leaves the cell"}'::jsonb, 'Sees the membrane as the edge of the drawing, like a wall.', 'Offer "Gives the cell its shape only" next to the right answer in a new question and ask the child to choose.', 'Think of a gate that lets some things in.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.THE_CELL.MAGNIFICATION.M_G8_MG_ADD', 'INTE.G8.LIVING.THE_CELL.MAGNIFICATION', 'Adds the eyepiece and the objective magnifications.', '{"question":"The eyepiece is 10 times and the objective is 40 times. What is the total magnification?","wrong_answer":"50 times","correct_answer":"400 times"}'::jsonb, 'Uses addition because there are "two numbers to combine".', 'Offer "50 times" next to the right answer in a new question and ask the child to choose.', 'Look at each lens: the second lens magnifies the image of the first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.THE_CELL.MAGNIFICATION.M_G8_MG_ONE', 'INTE.G8.LIVING.THE_CELL.MAGNIFICATION', 'Uses only the objective lens.', '{"question":"The eyepiece is 10 times and the objective is 10 times. What is the total magnification?","wrong_answer":"10 times","correct_answer":"100 times"}'::jsonb, 'Looks only at the lens closest to the slide.', 'Offer "10 times" next to the right answer in a new question and ask the child to choose.', 'Ask what the eyepiece does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.THE_CELL.MAGNIFICATION.M_G8_MG_FOUR', 'INTE.G8.LIVING.THE_CELL.MAGNIFICATION', 'Multiplies 10 by 40 and writes 40 or 140, losing the zero or adding instead.', '{"question":"What is 10 times 40?","wrong_answer":"40","correct_answer":"400"}'::jsonb, 'Slips in the multiplication by ten once the rule (multiply) is known.', 'Offer "40" next to the right answer in a new question and ask the child to choose.', 'Add a zero.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.THE_CELL.MAGNIFICATION.M_G8_MG_REAL_SIZE', 'INTE.G8.LIVING.THE_CELL.MAGNIFICATION', 'Thinks the magnification makes the cell itself bigger, rather than its image.', '{"question":"A cell looks 400 times bigger under a microscope. Has the cell grown?","wrong_answer":"Yes, the microscope makes the cell bigger","correct_answer":"No: only its image is bigger; the cell stays the same size"}'::jsonb, 'Talks about "making it bigger" and takes it literally.', 'Offer "Yes, the microscope makes the cell bigger" next to the right answer and ask the question again in a new context.', 'Look at a printed letter e through a hand lens, then without it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS.M_G8_DO_UP_GRADIENT', 'INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS', 'Says particles move from where they are few to where they are many.', '{"question":"In diffusion, particles move from...","wrong_answer":"Few to many","correct_answer":"Many to few"}'::jsonb, 'Thinks of particles "going to join the others", like people joining a crowd.', 'Offer "Few to many" next to the right answer in a new question and ask the child to choose.', 'Open a bottle of perfume at the front of a room.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS.M_G8_DO_OSMOSIS_SOLUTE', 'INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS', 'Says osmosis is the movement of solutes.', '{"question":"What moves in osmosis?","wrong_answer":"Dissolved salt","correct_answer":"Water"}'::jsonb, 'Since the salt is what is different, the child thinks it must be what moves.', 'Offer "Dissolved salt" next to the right answer in a new question and ask the child to choose.', 'Soak a raisin and a dry bean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS.M_G8_DO_ENERGY', 'INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS', 'Says diffusion needs energy from the cell.', '{"question":"Does diffusion need energy from the cell?","wrong_answer":"Yes, always","correct_answer":"No, particles move by themselves"}'::jsonb, 'Has learnt that living cells need energy for everything they do.', 'Offer "Yes, always" next to the right answer in a new question and ask the child to choose.', 'Ask what makes the smell of cooking spread.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS_DEMO.M_G8_DD_SALT_INTO_POTATO', 'INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS_DEMO', 'Says a potato strip in salty water goes soft because the salt goes into it, not because water leaves it.', '{"question":"A raw potato strip left in very salty water becomes soft and shorter. Why?","wrong_answer":"Salt went into the potato and made it soft","correct_answer":"Water moved out of the potato into the salty water by osmosis"}'::jsonb, 'Sees salt as the thing that acts and does not picture water moving out.', 'Offer "Salt went into the potato and made it soft" next to the right answer in a new question and ask the child to choose.', 'Weigh the strips before and after: the strip in salty water is lighter, so something left it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS_DEMO.M_G8_DD_STIRRING_NEEDED', 'INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS_DEMO', 'Thinks a dye dropped into still water stays in one spot unless the water is stirred.', '{"question":"A drop of dye is put in a glass of still water and left. What happens after an hour?","wrong_answer":"It stays as a drop at the bottom","correct_answer":"The colour spreads through the water until it is even"}'::jsonb, 'Has only seen colour spread when stirring.', 'Offer "It stays as a drop at the bottom" next to the right answer in a new question and ask the child to choose.', 'Leave a drop of food colour in still water on a desk for a lesson and look every ten minutes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS_DEMO.M_G8_DD_RAISIN_SHRINKS', 'INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS_DEMO', 'Predicts a raisin soaked in plain water will shrink.', '{"question":"A raisin is left in plain water overnight. What happens to it?","wrong_answer":"It shrinks","correct_answer":"It swells, because water moves into it by osmosis"}'::jsonb, 'Thinks water washes things away or dissolves them.', 'Offer "It shrinks" next to the right answer in a new question and ask the child to choose.', 'Soak a raisin and a dry bean overnight and compare them with dry ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS_DEMO.M_G8_DD_HOT_SLOWER', 'INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS_DEMO', 'Thinks diffusion is faster in cold water than in hot water.', '{"question":"Dye is dropped into a cold glass and a hot glass of water. In which does it spread faster?","wrong_answer":"The cold glass","correct_answer":"The hot glass: the particles move faster"}'::jsonb, 'Has not linked temperature with how fast particles move.', 'Offer "The cold glass" next to the right answer in a new question and ask the child to choose.', 'The teacher drops dye into warm and cold water side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS.M_G8_DO_ONLY_LIQUIDS', 'INTE.G8.LIVING.MOVEMENT_OF_MATERIALS_IN.DIFFUSION_OSMOSIS', 'Thinks diffusion happens only in liquids, not in gases.', '{"question":"Does diffusion happen in air?","wrong_answer":"No, only in water","correct_answer":"Yes: the smell of cooking spreads through a house by diffusion"}'::jsonb, 'Has seen diffusion taught with dye in water.', 'Offer "No, only in water" next to the right answer and ask the question again in a new context.', 'Spray perfume at the front of the room and ask learners to raise a hand when they smell it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL.M_G8_MC_LENGTH', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL', 'Gives the length of the bleeding (about 7 days) as the length of the whole menstrual cycle (about 28 days).', '{"question":"About how long is the menstrual cycle?","wrong_answer":"About 7 days","correct_answer":"About 28 days"}'::jsonb, 'Knows the period lasts a few days and takes the period to be the whole cycle.', 'Offer "About 7 days" next to the right answer in a new question and ask the child to choose.', 'Count the days on a calendar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL.M_G8_MC_OVULATION', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL', 'Says an egg is released at the start of the cycle.', '{"question":"When is an egg released?","wrong_answer":"At the start of the bleeding","correct_answer":"About the middle of the cycle"}'::jsonb, 'Thinks the cycle "starts" with the egg because bleeding is the first thing noticed.', 'Offer "At the start of the bleeding" next to the right answer in a new question and ask the child to choose.', 'Mark the days on a cycle chart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL.M_G8_MC_DISEASE', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL', 'Says menstruation is an illness.', '{"question":"What is menstruation?","wrong_answer":"An illness","correct_answer":"A normal part of growing up"}'::jsonb, 'Has seen girls in pain or staying home and links it with being ill.', 'Offer "An illness" next to the right answer in a new question and ask the child to choose.', 'Talk with a trusted adult or the school nurse.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.FERTILISATION.M_G8_FE_PLACE', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.FERTILISATION', 'Says fertilisation happens in the uterus.', '{"question":"Where does fertilisation happen?","wrong_answer":"In the uterus","correct_answer":"In the oviduct"}'::jsonb, 'Knows the baby grows in the uterus and puts the start of it there too.', 'Offer "In the uterus" next to the right answer in a new question and ask the child to choose.', 'Trace the path on a chart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.FERTILISATION.M_G8_FE_ORDER', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.FERTILISATION', 'Puts implantation before fertilisation.', '{"question":"Which happens first?","wrong_answer":"Implantation","correct_answer":"Fertilisation"}'::jsonb, 'Has learnt the two words together without the order of events.', 'Offer "Implantation" next to the right answer in a new question and ask the child to choose.', 'Put the events on cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.FERTILISATION.M_G8_FE_ZYGOTE', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.FERTILISATION', 'Says the zygote is the baby when it is born.', '{"question":"What is a zygote?","wrong_answer":"A newborn baby","correct_answer":"The first cell made when sperm joins egg"}'::jsonb, 'Has heard "zygote" as a science word for a baby.', 'Offer "A newborn baby" next to the right answer in a new question and ask the child to choose.', 'Look at the stages on a chart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.STIS.M_G8_STI_MYTH', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.STIS', 'Says STIs spread by hugging or toilet seats.', '{"question":"Which does NOT spread an STI?","wrong_answer":"Unprotected sex","correct_answer":"Hugging"}'::jsonb, 'Has heard myths from friends and fears catching any illness by touch.', 'Offer "Unprotected sex" next to the right answer in a new question and ask the child to choose.', 'Ask a health worker how STIs spread.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.STIS.M_G8_STI_NO_CURE', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.STIS', 'Says STIs are never treated.', '{"question":"What should a person with symptoms of an STI do?","wrong_answer":"Nothing, they cannot be treated","correct_answer":"See a health worker for testing and treatment"}'::jsonb, 'Has heard that HIV has no cure and applies it to every STI.', 'Offer "Nothing, they cannot be treated" next to the right answer in a new question and ask the child to choose.', 'Ask a health worker.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.STIS.M_G8_STI_PREVENT', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.STIS', 'Thinks washing the body after sex prevents STIs, instead of abstinence, faithfulness to one uninfected partner or correct condom use.', '{"question":"Which helps to prevent STIs?","wrong_answer":"Washing the body after sex","correct_answer":"Abstinence and faithfulness"}'::jsonb, 'Thinks of an STI like dirt that can be washed off.', 'Offer "Washing the body after sex" next to the right answer in a new question and ask the child to choose.', 'Ask a health worker.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL_MANAGE.M_G8_MM_STAY_HOME', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL_MANAGE', 'Thinks a girl should stay home from school during her period.', '{"question":"A girl starts her period at school. What is the best plan?","wrong_answer":"Go home and stay away for the week","correct_answer":"Use a pad (from her bag or the school nurse), carry on with school and tell a trusted adult if she needs help"}'::jsonb, 'Has heard that periods mean missing school.', 'Offer "Go home and stay away for the week" next to the right answer in a new question and ask the child to choose.', 'Plan with the class what a spare-pad kit and the school nurse can do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL_MANAGE.M_G8_MM_ONE_PAD_DAY', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL_MANAGE', 'Thinks one pad can be used for a whole day.', '{"question":"How often should a pad be changed?","wrong_answer":"Once a day","correct_answer":"Every four to six hours, or more often if bleeding is heavy"}'::jsonb, 'Wants to save pads and does not know about germs and smell.', 'Offer "Once a day" next to the right answer in a new question and ask the child to choose.', 'Talk about germs and skin irritation from a pad left too long.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL_MANAGE.M_G8_MM_SEVERE_NORMAL', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL_MANAGE', 'Thinks very heavy bleeding or pain that stops a girl walking is normal and needs no health worker.', '{"question":"A girl has pain so bad she cannot walk, every month. What should she do?","wrong_answer":"Nothing, all periods are painful","correct_answer":"See a health worker"}'::jsonb, 'Has heard that cramps are normal and applies it to every pain.', 'Offer "Nothing, all periods are painful" next to the right answer in a new question and ask the child to choose.', 'List signs that need a health worker: pain that stops daily life, very heavy bleeding, periods lasting more than a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL_MANAGE.M_G8_MM_SECRET', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL_MANAGE', 'Thinks a girl must never talk to any adult about her period.', '{"question":"Who can a girl talk to about her period?","wrong_answer":"No one, it must stay secret","correct_answer":"A trusted adult: a parent, the school nurse or a female teacher"}'::jsonb, 'Has learnt that periods are not talked about.', 'Offer "No one, it must stay secret" next to the right answer in a new question and ask the child to choose.', 'Name trusted adults at home and at school with the class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL.M_G8_MC_ALWAYS_REGULAR', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.MENSTRUAL', 'Thinks every girl''s cycle is exactly 28 days from the start, so a shorter or irregular cycle means illness.', '{"question":"A 13-year-old''s cycle is 25 days one month and 32 the next. Is she ill?","wrong_answer":"Yes, it must be exactly 28 days","correct_answer":"Not necessarily: cycles vary, especially in the first years; see a health worker if worried"}'::jsonb, 'Takes the textbook number as a rule.', 'Offer "Yes, it must be exactly 28 days" next to the right answer and ask the question again in a new context.', 'Explain that 28 days is an average; 21 to 35 days is common.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.FERTILISATION.M_G8_FE_MANY_SPERM', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.FERTILISATION', 'Thinks many sperm join one egg to make a baby.', '{"question":"How many sperm join the egg at fertilisation?","wrong_answer":"Many sperm","correct_answer":"One sperm"}'::jsonb, 'Has heard that millions of sperm are released.', 'Offer "Many sperm" next to the right answer and ask the question again in a new context.', 'Draw one sperm entering the egg; the egg then blocks the others.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.STIS.M_G8_STI_NO_SYMPTOMS_SAFE', 'INTE.G8.LIVING.REPRODUCTION_IN_HUMAN_BE.STIS', 'Thinks a person with no symptoms cannot have or pass on an STI.', '{"question":"Can a person with no signs of an STI pass it on?","wrong_answer":"No, they would have signs","correct_answer":"Yes: some STIs show no signs for a long time; testing is the way to know"}'::jsonb, 'Expects every illness to show.', 'Offer "No, they would have signs" next to the right answer and ask the question again in a new context.', 'Talk about testing at a health centre as the only way to know.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_FORMS_SOURCES.M_G8_EN_RENEWABLE_COAL', 'INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_FORMS_SOURCES', 'Calls coal a renewable source.', '{"question":"Which is a renewable source?","wrong_answer":"Coal","correct_answer":"The sun"}'::jsonb, 'Coal is dug from the ground every year, so it seems to be always there.', 'Offer "Coal" next to the right answer in a new question and ask the child to choose.', 'Ask what will run out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_FORMS_SOURCES.M_G8_EN_SOLAR_NONREN', 'INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_FORMS_SOURCES', 'Calls solar or wind energy non-renewable.', '{"question":"Which is a non-renewable source?","wrong_answer":"Wind","correct_answer":"Petroleum"}'::jsonb, 'Thinks the sun or wind can "run out" on a cloudy or still day.', 'Offer "Wind" next to the right answer in a new question and ask the child to choose.', 'Ask what is replaced by nature.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_FORMS_SOURCES.M_G8_EN_FORM_MIX', 'INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_FORMS_SOURCES', 'Mixes up the forms of energy.', '{"question":"Which form of energy does a rolling ball have?","wrong_answer":"Chemical energy","correct_answer":"Kinetic energy"}'::jsonb, 'Knows the names of the forms but not what each looks like in a real object.', 'Offer "Chemical energy" next to the right answer in a new question and ask the child to choose.', 'Link the form with what the object is doing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_TRANSFORM.M_G8_ET_KETTLE_LIGHT', 'INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_TRANSFORM', 'Says an electric kettle changes electrical energy mainly into light (its indicator glows) rather than heat.', '{"question":"What does an electric kettle change electrical energy into?","wrong_answer":"Light","correct_answer":"Heat"}'::jsonb, 'Notices the glowing light on the kettle and names what is seen.', 'Offer "Light" next to the right answer in a new question and ask the child to choose.', 'Ask what the kettle gives out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_TRANSFORM.M_G8_ET_CREATED', 'INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_TRANSFORM', 'Says energy is created or used up.', '{"question":"What happens to energy when it is used?","wrong_answer":"It is used up and disappears","correct_answer":"It changes into other forms"}'::jsonb, 'Everyday speech says batteries and fuel are "used up".', 'Offer "It is used up and disappears" next to the right answer in a new question and ask the child to choose.', 'Follow the energy of a falling stone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_TRANSFORM.M_G8_ET_SOLAR', 'INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_TRANSFORM', 'Gives sound or heat, not electrical energy, as what a solar panel changes light into.', '{"question":"What does a solar panel change light into?","wrong_answer":"Sound","correct_answer":"Electrical energy"}'::jsonb, 'Has seen solar radios and solar heaters and names their end use.', 'Offer "Sound" next to the right answer in a new question and ask the child to choose.', 'Link a solar lamp to the sun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_FORMS_SOURCES.M_G8_EN_FOOD_NOT_ENERGY', 'INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_FORMS_SOURCES', 'Does not see food as a store of chemical energy.', '{"question":"What form of energy is stored in a plate of ugali?","wrong_answer":"None, food is not energy","correct_answer":"Chemical energy"}'::jsonb, 'Thinks of energy as electricity or movement only.', 'Offer "None, food is not energy" next to the right answer and ask the question again in a new context.', 'Link food to activity: after eating we can run and keep warm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_TRANSFORM.M_G8_ET_ONE_STEP', 'INTE.G8.FORCE_.TRANSFORMATION_OF_ENERGY.ENERGY_TRANSFORM', 'Gives only one change when there is a chain, for example a torch changes chemical energy straight into light.', '{"question":"Write the energy changes in a torch.","wrong_answer":"Chemical to light","correct_answer":"Chemical to electrical to light (and some heat)"}'::jsonb, 'Skips the middle step that cannot be seen.', 'Offer "Chemical to light" next to the right answer and ask the question again in a new context.', 'Follow the torch: battery, wire, bulb; name the energy at each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.FORCE_.PRESSURE.PRESSURE.M_G8_PR_FORCE_ONLY', 'INTE.G8.FORCE_.PRESSURE.PRESSURE', 'Says pressure depends only on the force.', '{"question":"The same force acts on a small area and a large area. Where is the pressure bigger?","wrong_answer":"The same in both","correct_answer":"On the small area"}'::jsonb, 'Thinks of pressure as the same as pushing, so only the size of the push matters.', 'Offer "The same in both" next to the right answer in a new question and ask the child to choose.', 'Press a finger and a nail into soft clay.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.FORCE_.PRESSURE.PRESSURE.M_G8_PR_AREA_WRONG', 'INTE.G8.FORCE_.PRESSURE.PRESSURE', 'Says a larger area gives more pressure.', '{"question":"Why do wide tyres sink less in mud?","wrong_answer":"They give more pressure","correct_answer":"They give less pressure"}'::jsonb, 'Thinks a bigger thing must press harder.', 'Offer "They give more pressure" next to the right answer in a new question and ask the child to choose.', 'Compare walking in boots and in snow shoes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.FORCE_.PRESSURE.PRESSURE.M_G8_PR_DEPTH', 'INTE.G8.FORCE_.PRESSURE.PRESSURE', 'Says pressure in a liquid stays the same with depth.', '{"question":"How does liquid pressure change with depth?","wrong_answer":"It stays the same","correct_answer":"It increases"}'::jsonb, 'Thinks water is the same everywhere in a tank, so its push is too.', 'Offer "It stays the same" next to the right answer in a new question and ask the child to choose.', 'Poke holes at different heights in a bottle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G8.FORCE_.PRESSURE.PRESSURE.M_G8_PR_SHAPE_TANK', 'INTE.G8.FORCE_.PRESSURE.PRESSURE', 'Thinks a wider tank of water gives more pressure at the bottom than a narrow one of the same depth.', '{"question":"Two tanks of water are both 2 m deep; one is wide and one narrow. Where is the pressure at the bottom bigger?","wrong_answer":"In the wide tank, it holds more water","correct_answer":"The same in both: liquid pressure depends on depth, not width"}'::jsonb, 'Thinks more water means more pressure.', 'Offer "In the wide tank, it holds more water" next to the right answer and ask the question again in a new context.', 'Fill a wide and a narrow bottle to the same height, with a hole at the same low point: the jets go the same distance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
